```ts
/** What an answers-request dispatch learns from one read of the thread. */
export interface LastTurnRead {
  /**
   * Whether the comment the caller named as its freshness probe is in the listing
   * yet, or `undefined` when it named none. The same instrument `MarkerCheck`'s
   * marker is: while this dispatch's own recent write is not visible, the read has
   * not caught up, and an answer judged on it could be an answer about an older
   * thread.
   */
  probeVisible: boolean | undefined;
  /** The newest turn event in the shaped thread, or `undefined` when it carries none. */
  last: TurnEvent | undefined;
}

/**
 * Read a node's thread once and answer what an answers-request dispatch judges on.
 *
 * `answersRequest` claims the request this dispatch fulfils is the thread's own last
 * event; the claim is the caller's, and this read is what makes it checkable — see
 * `adapters/actions/dispatch.ts`. The probe is the caller's just-written comment, when
 * it has one (`reload_environment`'s handoff comment): until the listing shows it, the
 * read may predate the write the claim rests on, and judging then would judge the
 * thread as it was before the caller spoke. Throws when the read fails, like every
 * other reader here.
 */
export function readLastTurnEvent(
  repo: string,
  number: string | number,
  probeId?: string | number,
): LastTurnRead {
  const comments = listComments(repo, number);
  const probe = probeId === undefined ? undefined : String(probeId);
  return {
    probeVisible: probe === undefined ? undefined : comments.some((comment) => String(comment.id) === probe),
    last: shapedThread(comments, readers).events.at(-1),
  };
}
```

